let tab='storms',storm='solar',paused=reduce.matches,voice=soundOn(),globe,surface,frame=0,last=0,time=0,weather=null,solar={...FALLBACK_EVENT,mode:'archive'},surfaceMode=false,spot={lat:-5.4,lon:137.8},held=new Set(),pointers=new Map(),gesture=null,dirty=true;
const header=()=>`<header class="explorer-header"><div><h1>${t('explorerTitle')}</h1><p>${t('explorerSubtitle')}</p></div><a class="back-link" href="./">← ${t('explorerHome')}</a></header>`;
